window.World={theme(t){load(t)},update(s,i){state=s;selected=i;$('selectedLabel').textContent=i>=0?'Ligne '+(Math.floor(i/9)+1)+' · colonne '+(i%9+1):'Choisissez une case';progress(s);if(board3d)board3d.update(s,i,theme)},event:gameEvent,motion(v){reduced=v;document.body.classList.toggle('motion-reduced',v)},pause(v){paused=v;if(renderer&&map&&camera&&!hidden&&v)renderer.render(scene,camera)},reset(){time=0;state=null;currentProgress=-1;completeSet.clear();firstUpdate=true;needsMap=true},refresh(){resizePending=true},details(){return{theme,models:map?.props.length||0,actors:map?.actors.length||0,progress:currentProgress,sceneCells:board3d?.tiles.length||0,behaviours:brains?.snapshot()||[]}},behaviours(){return brains?.snapshot()||[]}};
